    {
      "rank": 1,
      "ballot_id": "B043",
      "proposed_laureates": [
        "Alexandre Blais",
        "Robert J. Schoelkopf",
        "Steven M. Girvin"
      ],
      "assessment": {
        "nobel_worthiness": "Circuit QED made strong, controllable coupling between individual microwave photons and superconducting artificial atoms a practical regime, opening a major experimental platform for quantum optics and quantum information.",
        "attribution": "Blais's theory and the Schoelkopf-Girvin experimental and theoretical program are central to the framework and its demonstration. Credit should reflect the joint character of the advance.",
        "maturity": "The regime has been reproduced widely and developed into a sustained platform for precise control of quantum systems.",
        "uncertainties": [
          "The boundary between the founding demonstration and the subsequent development of superconducting quantum computing is difficult to draw.",
          "My field connection to superconducting circuits warrants particular care about attribution."
        ]
      }
    },
    {
      "rank": 2,
      "ballot_id": "B038",
      "proposed_laureates": [
        "Alexei Kitaev",
        "Andrew M. Steane",
        "Peter W. Shor"
      ],
      "assessment": {
        "nobel_worthiness": "Quantum error correction and fault tolerance showed how quantum computation can overcome noise in principle and supplied deep physical ideas, including topological codes, that continue to shape the field.",
        "attribution": "Shor and Steane established influential quantum error-correcting codes, while Kitaev developed foundational topological approaches. Their contributions are distinct and complementary.",
        "maturity": "The theory is established and has guided experiments for decades; practical fault-tolerant computing remains an active experimental challenge.",
        "uncertainties": [
          "The broad description combines several advances whose boundaries and relative weight could be framed differently."
        ]
      }
    },
    {
      "rank": 3,
      "ballot_id": "B051",
      "proposed_laureates": [
        "Hidetoshi Katori",
        "Jun Ye"
      ],
      "assessment": {
        "nobel_worthiness": "Optical lattice clocks brought atomic timekeeping to unprecedented precision and opened new tests of fundamental physics and precision measurement.",
        "attribution": "Katori's lattice clock concept and Ye's influential experimental development are clear, complementary contributions.",
        "maturity": "The technique is robust across laboratories and has advanced to extraordinary precision, with clear scientific uses beyond metrology.",
        "uncertainties": [
          "The case rests partly on whether precision measurement and its enabling technology are judged a sufficiently fundamental discovery."
        ]
      }
    },
    {
      "rank": 4,
      "ballot_id": "B004",
      "proposed_laureates": [
        "Alessandra Buonanno",
        "Frans Pretorius",
        "Thibault Damour"
      ],
      "assessment": {
        "nobel_worthiness": "Effective-one-body theory and numerical relativity made reliable predictions for binary black-hole mergers possible, enabling gravitational-wave observations to become quantitative tests of strong-field gravity.",
        "attribution": "Damour and Buonanno developed the effective-one-body framework; Pretorius achieved the breakthrough numerical simulations. The nominated group captures complementary advances.",
        "maturity": "The methods have been validated by repeated gravitational-wave detections and remain central to interpreting them.",
        "uncertainties": [
          "The discovery description spans theory, computational breakthroughs, and their later role in observations, making the prize boundary broad."
        ]
      }
    },
    {
      "rank": 5,
      "ballot_id": "B014",
      "proposed_laureates": [
        "Carlton M. Caves",
        "H. Jeff Kimble",
        "Nergis Mavalvala"
      ],
      "assessment": {
        "nobel_worthiness": "Squeezed light demonstrated a way to reduce measurement noise below the standard quantum limit and has materially improved precision interferometry, including gravitational-wave detection.",
        "attribution": "Caves established key theory, Kimble helped develop the quantum-optics approach, and Mavalvala led important interferometric demonstrations and implementation. The full experimental lineage is broader.",
        "maturity": "The method is established in gravitational-wave observatories, where its performance can be tested against real measurements.",
        "uncertainties": [
          "The proposed attribution may omit other major contributors to theory, demonstrations, and observatory deployment.",
          "The distinction between the foundational physics and the later engineering achievement needs care."
        ]
      }
    },
    {
      "rank": 6,
      "ballot_id": "B005",
      "proposed_laureates": [
        "Charles L. Kane",
        "Eugene J. Mele",
        "Laurens W. Molenkamp"
      ],
      "assessment": {
        "nobel_worthiness": "The quantum spin Hall effect and time-reversal-invariant topological insulators established a new phase of matter with robust boundary states and reshaped condensed-matter physics.",
        "attribution": "Kane and Mele provided the seminal theory; Molenkamp's experiments made the quantum spin Hall phase observable. This is a strong theory-experiment pairing.",
        "maturity": "The core phenomena have been independently investigated and the topological framework now spans many material systems.",
        "uncertainties": [
          "The idealized early material realization differs from later, more robust examples, so the nominated experimental milestone should be specified carefully."
        ]
      }
    },
    {
      "rank": 7,
      "ballot_id": "B001",
      "proposed_laureates": [
        "Peter F. Moulton",
        "Ursula Keller",
        "Wilson Sibbett"
      ],
      "assessment": {
        "nobel_worthiness": "The titanium-sapphire laser and passive mode locking made reliable femtosecond solid-state pulses broadly accessible, transforming ultrafast science and measurement.",
        "attribution": "Moulton's laser medium and Keller's and Sibbett's mode-locking advances are distinct, consequential contributions to the resulting platform.",
        "maturity": "The technology has had decades of widespread use and its impact is well established.",
        "uncertainties": [
          "The discovery combines a laser material with multiple mode-locking methods, and the relative credit depends on how the advance is defined."
        ]
      }
    },
    {
      "rank": 8,
      "ballot_id": "B009",
      "proposed_laureates": [
        "Jocelyn Bell Burnell"
      ],
      "assessment": {
        "nobel_worthiness": "The discovery of pulsars revealed neutron stars as observable astrophysical objects and opened a durable new field of precision radio astronomy.",
        "attribution": "Bell Burnell made the crucial observations and recognized the signal. The discovery involved a research group, so awarding her alone would recognize the especially important observational role rather than imply sole authorship.",
        "maturity": "Pulsars have been studied for decades and underpin major tests of gravitation and dense-matter physics.",
        "uncertainties": [
          "The original discovery's group attribution is complex, and the case for an individual prize requires an explicit judgment about credit."
        ]
      }
    }
  ]
